DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_animal_skill_operation'' OR ')); END $$;
CREATE TABLE cmd_animal_skill_operation_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,operation_rule_id bigint NOT NULL,operation_code text NOT NULL,subject_animal_actor_id bigint,objective_reference text NOT NULL CHECK(btrim(objective_reference)<>''),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint NOT NULL,effect smallint NOT NULL,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(subject_animal_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(subject_animal_actor_id) REFERENCES actor_animal_profile(actor_id),FOREIGN KEY(operation_rule_id,operation_code) REFERENCES rule_animal_skill_operation(rule_id,operation_code));
CREATE FUNCTION cmd_reject_animal_skill_operation_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Animal skill operation receipts are immutable'; END $$;
CREATE TRIGGER cmd_animal_skill_operation_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_animal_skill_operation_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_animal_skill_operation_mutation();
